import { EmptyState } from '@kerfjs/ui/empty-state';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import { StateBanner } from '@kerfjs/ui/state-banner';
import '@kerfjs/ui/layout.css';

type Item = { id: string; title: string };
type WorkspaceState =
  | { phase: 'loading'; items: [] }
  | { phase: 'ready'; items: Item[] }
  | { phase: 'refreshing'; items: Item[] }
  | { phase: 'failed'; items: Item[]; message: string };

type Props = { state: WorkspaceState; retry: () => void; createItem: () => void };

export function ListWorkspace({ state, retry, createItem }: Props) {
  if (state.phase === 'loading') {
    return <main className="kui-layout kui-page" aria-busy="true"><LoadingSpinner label="Loading items" /></main>;
  }

  const hasItems = state.items.length > 0;
  return (
    <main className="kui-layout kui-page" aria-busy={state.phase === 'refreshing'}>
      <h1>Items</h1>
      {state.phase === 'refreshing' && (
        <StateBanner tone="info"><LoadingSpinner label="Refreshing items" /> Showing saved items while refreshing.</StateBanner>
      )}
      {state.phase === 'failed' && (
        <StateBanner tone="danger" role="alert">
          <strong>Refresh failed.</strong> {state.message} <button type="button" onClick={retry}>Try again</button>
        </StateBanner>
      )}
      {hasItems ? (
        <ul aria-label="Items">{state.items.map(item => <li key={item.id}>{item.title}</li>)}</ul>
      ) : state.phase === 'failed' ? (
        <p>No items could be loaded. Use Try again to recover.</p>
      ) : (
        <EmptyState title="No items yet" description="Create the first item for this workspace." action={<button type="button" onClick={createItem}>Create item</button>} />
      )}
    </main>
  );
}
